css:
.verveine-sim-container {
    padding: 20px;
    background: linear-gradient(160deg, #f4f1e8 0%, #eef2e6 55%, #e6ede0 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #2f3a30;
}

.verveine-sim-header {
    background: linear-gradient(135deg, #2f5d3f 0%, #3f7350 50%, #5c8a63 100%);
    color: #fbfaf3;
    padding: 32px 30px;
    border-radius: 16px;
    margin-bottom: 22px;
    box-shadow: 0 12px 30px rgba(47,93,63,0.28);
    text-align: center;
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,0.14);
}

.verveine-sim-header::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(212,175,90,0.14) 0%, transparent 60%);
    pointer-events: none;
}

.verveine-sim-header-icon {
    font-size: 2.6rem;
    margin-bottom: 8px;
}

.verveine-sim-header h1 {
    font-size: 1.95rem;
    font-weight: 800;
    margin-bottom: 6px;
    letter-spacing: 0.4px;
    font-family: Georgia, 'Times New Roman', serif;
}

.verveine-sim-header p {
    font-size: 1rem;
    opacity: 0.92;
    margin: 0 0 14px 0;
    letter-spacing: 0.6px;
}

.verveine-sim-clock {
    display: inline-block;
    background: rgba(0,0,0,0.22);
    border: 1px solid rgba(212,175,90,0.5);
    border-radius: 999px;
    padding: 6px 18px;
    font-size: 0.92rem;
    font-weight: 600;
    letter-spacing: 0.4px;
}

.verveine-sim-clock #deadlineDisplay {
    color: #f0cf7a;
    font-weight: 800;
    margin: 0 4px;
}

.verveine-sim-period-counter {
    text-align: center;
    font-size: 1.05rem;
    color: #4b5e4d;
    margin-bottom: 22px;
    font-weight: 600;
}

.verveine-sim-period-counter span {
    margin: 0 3px;
}

.verveine-sim-period-counter #currentDay,
.verveine-sim-period-counter #maxPeriods {
    color: #2f5d3f;
    font-weight: 800;
}

.verveine-sim-round-name {
    display: inline-block;
    margin-left: 10px;
    padding: 3px 14px;
    background: rgba(47,93,63,0.12);
    border: 1px solid rgba(47,93,63,0.3);
    border-radius: 999px;
    color: #2f5d3f;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

/* ---- KPI cards ---- */
.verveine-sim-kpi-section {
    margin-bottom: 22px;
}

.verveine-sim-kpi-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 16px;
}

.verveine-sim-kpi-cards-secondary {
    grid-template-columns: repeat(3, 1fr);
    margin-bottom: 0;
}

.verveine-sim-kpi-card {
    background: #fdfcf6;
    border: 1px solid rgba(47,93,63,0.12);
    border-radius: 14px;
    padding: 18px 18px 20px;
    box-shadow: 0 6px 18px rgba(47,93,63,0.1);
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.verveine-sim-kpi-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 26px rgba(47,93,63,0.18);
}

.verveine-kpi-hero {
    border: 1px solid rgba(212,175,90,0.55);
    background: linear-gradient(160deg, #fbf7e9 0%, #fdfcf6 100%);
}

.verveine-sim-kpi-label {
    font-size: 0.8rem;
    color: #6b7d6c;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 8px;
    font-weight: 700;
}

.verveine-sim-kpi-value {
    font-size: 2.6rem;
    font-weight: 800;
    color: #2f3a30;
    line-height: 1.05;
}

.verveine-kpi-hero .verveine-sim-kpi-value {
    color: #2f5d3f;
}

.verveine-kpi-small .verveine-sim-kpi-value {
    font-size: 1.5rem;
    color: #2f5d3f;
}

.verveine-sim-kpi-sub {
    font-size: 0.74rem;
    color: #8a978a;
    margin-top: 8px;
    line-height: 1.3;
}

.verveine-sim-kpi-bar-bg {
    height: 8px;
    background: rgba(47,93,63,0.1);
    border-radius: 6px;
    margin-top: 12px;
    overflow: hidden;
}

.verveine-sim-kpi-bar-fill {
    height: 100%;
    border-radius: 6px;
    transition: width 0.5s ease;
}

.verveine-fit-fill { background: linear-gradient(90deg, #3f7350, #6db07a); }
.verveine-pharmacy-fill { background: linear-gradient(90deg, #4a7fb0, #74a7d4); }
.verveine-diff-fill { background: linear-gradient(90deg, #b8923a, #e3c071); }
.verveine-value-fill { background: linear-gradient(90deg, #8a5a9e, #b487c7); }

/* ---- Briefing ---- */
.verveine-sim-briefing {
    background: #fdfcf6;
    border: 1px solid rgba(47,93,63,0.12);
    border-left: 4px solid #b8923a;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(47,93,63,0.1);
}

.verveine-sim-briefing h3 {
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #b8923a;
    font-family: Georgia, 'Times New Roman', serif;
}

.verveine-sim-briefing-text {
    font-size: 0.96rem;
    line-height: 1.65;
    color: #3c4a3d;
}

.verveine-sim-briefing-text strong {
    color: #2f5d3f;
}

.verveine-sim-briefing-text em {
    color: #8a5a9e;
    font-style: italic;
}

.verveine-sim-event-alert {
    margin-top: 16px;
    padding: 14px 16px;
    background: rgba(184,146,58,0.12);
    border: 1px solid rgba(184,146,58,0.45);
    border-radius: 10px;
    color: #7a611f;
    font-size: 0.92rem;
    line-height: 1.55;
}

/* ---- Controls ---- */
.verveine-sim-controls {
    background: #fdfcf6;
    border: 1px solid rgba(47,93,63,0.12);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(47,93,63,0.1);
}

.verveine-sim-controls h3 {
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 6px;
    color: #2f5d3f;
    font-family: Georgia, 'Times New Roman', serif;
}

.verveine-sim-decisions-note {
    font-size: 0.86rem;
    color: #6b7d6c;
    margin-bottom: 18px;
    font-style: italic;
}

.verveine-sim-input-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px 22px;
}

.verveine-sim-input-group {
    display: flex;
    flex-direction: column;
}

.verveine-sim-input-group label {
    font-size: 0.9rem;
    font-weight: 600;
    color: #3c4a3d;
    margin-bottom: 7px;
}

.verveine-sim-container .form-control {
    background-color: #ffffff;
    color: #2f3a30;
    border: 1px solid rgba(47,93,63,0.25);
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.95rem;
}

.verveine-sim-container .form-control:focus {
    border-color: #3f7350;
    box-shadow: 0 0 0 3px rgba(63,115,80,0.18);
    background-color: #ffffff;
    color: #2f3a30;
    outline: none;
}

.verveine-sim-container select.form-control {
    background-color: #ffffff;
    color: #2f3a30;
}

.verveine-sim-container select.form-control option {
    background-color: #ffffff;
    color: #2f3a30;
}

.verveine-sim-hint {
    font-size: 0.76rem;
    color: #8a978a;
    margin-top: 6px;
    line-height: 1.35;
}

.verveine-sim-budget-meter {
    margin-top: 20px;
    padding: 14px 16px;
    background: rgba(47,93,63,0.05);
    border: 1px solid rgba(47,93,63,0.14);
    border-radius: 10px;
}

.verveine-sim-budget-row {
    display: flex;
    align-items: baseline;
    gap: 8px;
    font-size: 0.9rem;
    font-weight: 600;
    color: #3c4a3d;
    margin-bottom: 8px;
}

.verveine-sim-budget-row #allocatedDisplay {
    font-size: 1.15rem;
    font-weight: 800;
    color: #2f5d3f;
}

.verveine-sim-budget-bar-bg {
    height: 10px;
    background: rgba(47,93,63,0.12);
    border-radius: 6px;
    overflow: hidden;
}

.verveine-sim-budget-bar-fill {
    height: 100%;
    border-radius: 6px;
    background: linear-gradient(90deg, #3f7350, #6db07a);
    transition: width 0.4s ease, background 0.4s ease;
}

.verveine-sim-budget-bar-fill.verveine-over {
    background: linear-gradient(90deg, #c0392b, #e57368);
}

.verveine-sim-btn-row {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-top: 22px;
    flex-wrap: wrap;
}

.verveine-sim-container .btn-primary {
    background: linear-gradient(135deg, #2f5d3f 0%, #5c8a63 100%);
    border: none;
    font-weight: 700;
    letter-spacing: 0.4px;
    padding: 12px 30px;
    border-radius: 10px;
    box-shadow: 0 6px 16px rgba(47,93,63,0.35);
    color: #fbfaf3;
}

.verveine-sim-container .btn-primary:hover {
    background: linear-gradient(135deg, #366b49 0%, #6a9b71 100%);
    color: #ffffff;
}

.verveine-sim-container .btn-outline-secondary {
    color: #4b5e4d;
    border-color: rgba(47,93,63,0.35);
    border-radius: 10px;
}

.verveine-sim-container .btn-outline-secondary:hover {
    background: rgba(47,93,63,0.08);
    color: #2f5d3f;
}

/* ---- Charts ---- */
.verveine-sim-charts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
    margin-bottom: 22px;
}

.verveine-sim-chart-box {
    background: #fdfcf6;
    border: 1px solid rgba(47,93,63,0.12);
    border-radius: 14px;
    padding: 16px;
    box-shadow: 0 6px 18px rgba(47,93,63,0.1);
    min-height: 320px;
}

/* ---- History ---- */
.verveine-sim-history {
    background: #fdfcf6;
    border: 1px solid rgba(47,93,63,0.12);
    border-radius: 14px;
    padding: 22px 24px;
    box-shadow: 0 6px 18px rgba(47,93,63,0.1);
}

.verveine-sim-history h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #2f5d3f;
    font-family: Georgia, 'Times New Roman', serif;
}

.verveine-sim-history table {
    color: #3c4a3d;
    margin-bottom: 0;
}

.verveine-sim-history .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(47,93,63,0.04);
}

.verveine-sim-history th {
    color: #6b7d6c;
    border-color: rgba(47,93,63,0.18);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.verveine-sim-history td {
    border-color: rgba(47,93,63,0.1);
    font-size: 0.88rem;
}

/* ---- Responsive ---- */
@media (max-width: 768px) {
    .verveine-sim-container {
        padding: 12px;
    }
    .verveine-sim-header h1 {
        font-size: 1.45rem;
    }
    .verveine-sim-kpi-cards,
    .verveine-sim-kpi-cards-secondary {
        grid-template-columns: 1fr;
    }
    .verveine-sim-input-grid {
        grid-template-columns: 1fr;
    }
    .verveine-sim-charts {
        grid-template-columns: 1fr;
    }
    .verveine-sim-kpi-value {
        font-size: 2.1rem;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.db-completion { padding: 8px 4px 4px; }
.db-cm-head { text-align: center; margin-bottom: 16px; }
.db-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #7c9a5e; }
.db-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #9a8f7e; }
.db-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; }
.db-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.db-cm-yes { background: rgba(124,154,94,0.16); color: #5f7a44; border: 1px solid rgba(124,154,94,0.4); }
.db-cm-no { background: rgba(180,90,70,0.12); color: #b45a46; border: 1px solid rgba(180,90,70,0.4); }
.db-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.db-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(124,154,94,0.07); border: 1px solid rgba(124,154,94,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.db-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #7c9a5e; }
.db-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #9a8f7e; text-transform: uppercase; letter-spacing: 0.03em; }
.db-cm-insights-title { font-weight: 700; margin: 8px 0 6px; }
.db-cm-insights { margin: 0; padding-left: 20px; }
.db-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; }

