                    pharmacyHistory: [],
                    diffHistory: [],
                    valueHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    dominantCode: 'sachet',
                    decodeDepth: 40,
                    narrative: 'evidence_calm',
                    dualCode: 50,
                    redesign: 1000,
                    trade: 700,
                    marketing: 700,
                    defense: 'balanced'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var codeEl = document.getElementById('dominantCodeInput');
            var depthEl = document.getElementById('decodeDepthInput');
            var narrEl = document.getElementById('narrativeInput');
            var dualEl = document.getElementById('dualCodeInput');
            var redesignEl = document.getElementById('redesignInput');
            var tradeEl = document.getElementById('tradeInput');
            var marketingEl = document.getElementById('marketingInput');
            var defenseEl = document.getElementById('defenseInput');

            if (codeEl) decisions.dominantCode = codeEl.value;
            if (depthEl) decisions.decodeDepth = parseInt(depthEl.value, 10);
            if (narrEl) decisions.narrative = narrEl.value;
            if (dualEl) decisions.dualCode = parseInt(dualEl.value, 10);
            if (redesignEl) decisions.redesign = parseInt(redesignEl.value, 10);
            if (tradeEl) decisions.trade = parseInt(tradeEl.value, 10);
            if (marketingEl) decisions.marketing = parseInt(marketingEl.value, 10);
            if (defenseEl) decisions.defense = defenseEl.value;

            if (['sachet', 'serif', 'green', 'none'].indexOf(decisions.dominantCode) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('code_warning'), 'warning');
                return false;
            }
            if (!Number.isFinite(decisions.decodeDepth) || decisions.decodeDepth < 0 || decisions.decodeDepth > 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('depth_warning'), 'warning');
                return false;
            }
            if (!this.NARRATIVES[decisions.narrative]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('narrative_warning'), 'warning');
                return false;
            }
            if (!Number.isFinite(decisions.dualCode) || decisions.dualCode < 0 || decisions.dualCode > 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('dualcode_warning'), 'warning');
                return false;
            }
            if (!Number.isFinite(decisions.redesign) || !Number.isFinite(decisions.trade) || !Number.isFinite(decisions.marketing) ||
                decisions.redesign < 0 || decisions.trade < 0 || decisions.marketing < 0) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_warning'), 'warning');
                return false;
            }
            if (decisions.redesign + decisions.trade + decisions.marketing > this.BUDGET_CAP) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_over_warning'), 'warning');
                return false;
            }
            if (['balanced', 'buyer', 'pharmacist', 'claim'].indexOf(decisions.defense) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('defense_warning'), 'warning');
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var n = this.NARRATIVES[d.narrative];

            // ---- Diagnosis: did the team find the load-bearing remedy code? ----
            // Truth = the blister sachet (material). decodeDepth governs how trustworthy the read is.
            var decodedRight = (d.dominantCode === this.TRUE_DOMINANT_CODE);
            var cosmeticOnly = (d.dominantCode === 'none');
            ds.decodedRight = decodedRight;
            // Depth multiplier: jumping to redesign with no decode caps every later gain.
            var depthFactor = 0.45 + (d.decodeDepth / 100) * 0.55; // 0.45 .. 1.0

            // ---- Budget mechanics (EUR thousands) ----
            var totalSpend = d.redesign + d.trade + d.marketing;
            ds.budgetSpent = totalSpend;
            var redesignK = d.redesign / 1000;     // 0 .. ~2.4
            var marketingK = d.marketing / 1000;
            var listingFunded = d.trade >= this.LISTING_FEE_FLOOR;

            // ---- Dual-code balance: 0 all-clinical .. 100 all-lifestyle. Sweet spot ~58. ----
            var balance = d.dualCode;
            // Ritual gain rises with balance; pharmacy trust falls as balance climbs past ~60.
            var ritualFromBalance = (balance / 100) * 14;                 // up to +14 fit
            var pharmacyFromBalance = balance <= 55 ? 2 : -((balance - 55) / 45) * 28; // betrayal penalty
            // A meaning-fit ceiling if you never edit the load-bearing code (still says pharmacy).
            var codeEditPower = 0;
            if (decodedRight) {
                // Editing the sachet (structural) needs real redesign spend to land.
                codeEditPower = Math.min(1, redesignK / 1.2);  // ~EUR 1.2M to fully re-engineer structure
            } else if (!cosmeticOnly) {
                // Editing a secondary code (serif/colour) is cheaper but only half-fixes the shelf.
                codeEditPower = Math.min(1, redesignK / 0.6) * 0.5;
            } else {
                // Cosmetic-only: trim changes, dominant remedy code intact -> shelf still reads medicine.
                codeEditPower = Math.min(1, redesignK / 0.6) * 0.2;
            }

            // ---- Meaning Fit (hero KPI) ----
            var fitGain = (n.fitRitual + ritualFromBalance) * codeEditPower * depthFactor;
            // Marketing delivers the new meaning to the shopper (diminishing returns).
            var marketingFit = Math.min(8, marketingK * 6);
            ds.meaningFit = Math.max(0, Math.min(100, Math.round(ds.meaningFit + fitGain + marketingFit * 0.5)));

            // ---- Pharmacy Trust ----
            var pharmacyDelta = n.keepsClinical + pharmacyFromBalance;
            // Ripping out the clinical signifier (sachet) without keeping any clinical cue erodes trust.
            if (decodedRight && balance > 70) pharmacyDelta -= 6;
            ds.pharmacyTrust = Math.max(0, Math.min(100, Math.round(ds.pharmacyTrust + pharmacyDelta)));

            // ---- Semiotic Differentiation ----
            var diffGain = n.ownable * depthFactor;
            // Generic wellness coding collides with the incoming competitor (already negative ownable).
            ds.differentiation = Math.max(0, Math.min(100, Math.round(ds.differentiation + diffGain)));

            // ---- Perceived Value: encoded, not asserted ----
            // Value lift only lands if a tangible cue actually changed (redesign on the right code).
            var valueGain = n.valueLift * codeEditPower * depthFactor;
            // Round 4 'claim' emphasis = assert premium without changing cues -> buyers don't believe it.
            if (period === 4 && d.defense === 'claim') valueGain -= 8;
            ds.perceivedValue = Math.max(0, Math.min(100, Math.round(ds.perceivedValue + valueGain + marketingFit * 0.4)));

            // ---- Round-3+ budget consequence: listing must be funded ----
            if (period >= 3) {
                if (!listingFunded) {
                    // The most beautiful pack off the shelf -> forfeit ~EUR 6M of grocery sales.
                    if (ds.listingStatus !== 'rejected') {
                        ds.financialImpact = Math.round((ds.financialImpact - 6) * 10) / 10;
                    }
                    ds.listingStatus = 'rejected';
                } else if (ds.meaningFit >= 50 && ds.differentiation >= 45) {
                    ds.listingStatus = 'secured';
                } else {
                    ds.listingStatus = 'pending';
                }
            }

            // ---- Round 4: pitch emphasis arbitration + final resolution ----
            if (period === 4) {
                // Emphasis nudges the two-audience read at the table.
                if (d.defense === 'buyer') {
                    ds.meaningFit = Math.min(100, ds.meaningFit + 4);
                    ds.pharmacyTrust = Math.max(0, ds.pharmacyTrust - 8); // pharmacist hears "no longer serious"
                } else if (d.defense === 'pharmacist') {
                    ds.pharmacyTrust = Math.min(100, ds.pharmacyTrust + 4);
                    ds.meaningFit = Math.max(0, ds.meaningFit - 8);       // grocery reads "still medicine"
                } else if (d.defense === 'balanced') {
                    ds.meaningFit = Math.min(100, ds.meaningFit + 2);
                    ds.pharmacyTrust = Math.min(100, ds.pharmacyTrust + 2);
                }

                // Final grocery listing decision (buyer skeptical of "another wellness tea").
                var listingCredible = listingFunded && ds.meaningFit >= 52 && ds.differentiation >= 45;
                if (listingCredible) {
                    ds.listingStatus = 'secured';
                    ds.financialImpact = Math.round((ds.financialImpact + 6) * 10) / 10; // EUR 6M year-one sales
                } else if (ds.listingStatus !== 'rejected') {
                    ds.listingStatus = 'rejected';
                    ds.financialImpact = Math.round((ds.financialImpact - 6) * 10) / 10;
                }

                // Pharmacy share: dilution below a credibility floor forfeits part of EUR 26M.
                if (ds.pharmacyTrust < 60) {
                    var lostShare = Math.round(26 * ((60 - ds.pharmacyTrust) / 60) * 10) / 10;
                    ds.financialImpact = Math.round((ds.financialImpact - lostShare) * 10) / 10;
                }

                // Purchase intent = the half-second shelf read: fit + value + differentiation, gated by trust.
                var trustGate = ds.pharmacyTrust >= 55 ? 1 : 0.8;
                ds.purchaseIntent = Math.round(
                    (ds.meaningFit * 0.40 + ds.perceivedValue * 0.30 + ds.differentiation * 0.30) * trustGate
                );
                ds.purchaseIntent = Math.max(0, Math.min(100, ds.purchaseIntent));

                var won = ds.listingStatus === 'secured' && ds.pharmacyTrust >= 62 &&
                          ds.meaningFit >= 55 && ds.differentiation >= 45 && ds.perceivedValue >= 50;
                ds.outcome = won ? 'won' : 'lost';
            } else {
                ds.outcome = 'inprogress';
            }

            // ---- History ----
            ds.fitHistory.push(ds.meaningFit);
            ds.pharmacyHistory.push(ds.pharmacyTrust);
            ds.diffHistory.push(ds.differentiation);
            ds.valueHistory.push(ds.perceivedValue);

            this._updateBars(ds);

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            var res = {
                period: period,
                dominantCode: d.dominantCode,
                decodeDepth: d.decodeDepth,
                narrative: d.narrative,
                dualCode: d.dualCode,
                redesign: d.redesign,
                trade: d.trade,
                marketing: d.marketing,
                defense: d.defense,
                decodedRight: decodedRight,
                meaningFit: ds.meaningFit,
                pharmacyTrust: ds.pharmacyTrust,
                differentiation: ds.differentiation,
                perceivedValue: ds.perceivedValue,
                budgetSpent: ds.budgetSpent,
                listingStatus: ds.listingStatus,
                purchaseIntent: ds.purchaseIntent,
                financialImpact: ds.financialImpact,
                outcome: ds.outcome
            };
            // Expose composite to the reporting/grading layer each period (results_utils.php reads
            // domainState.performance.overallScore); period 4 locks the authoritative score.
            ds.performance = { overallScore: this._composite(res) };
            return res;
        }

        _updateBars(ds) {
            var fit = document.getElementById('meaningFitBar');
            var pharm = document.getElementById('pharmacyBar');
            var diff = document.getElementById('differentiationBar');
            var val = document.getElementById('valueBar');
            if (fit) fit.style.width = ds.meaningFit + '%';
            if (pharm) pharm.style.width = ds.pharmacyTrust + '%';
            if (diff) diff.style.width = ds.differentiation + '%';
            if (val) val.style.width = ds.perceivedValue + '%';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = 'en';
            try {
                lang = (window.mySimulation && window.mySimulation.lang) ? window.mySimulation.lang : 'en';
            } catch (e) { lang = 'en'; }

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.briefingEs : round.briefingEn;
            }

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) {
                nameEl.textContent = lang === 'es' ? round.nameEs : round.nameEn;
            }

            var noteEl = document.getElementById('liveLeversNote');
            if (noteEl) {
                var noteKey = 'levers_note_r' + (idx + 1);
                try { noteEl.textContent = window.mySimulation.t(noteKey); } catch (e) {}
            }

            var eventEl = document.getElementById('eventAlert');
            if (eventEl) {
                var eventText = lang === 'es' ? round.eventEs : round.eventEn;
                if (eventText) {
                    eventEl.innerHTML = eventText;
                    eventEl.style.display = 'block';
                } else {
                    eventEl.style.display = 'none';
                }
            }

            this._updateBudgetMeter();
        }

        _updateBudgetMeter() {
            var rEl = document.getElementById('redesignInput');
            var tEl = document.getElementById('tradeInput');
            var mEl = document.getElementById('marketingInput');
            if (!rEl || !tEl || !mEl) return;
            var r = parseInt(rEl.value, 10) || 0;
            var t = parseInt(tEl.value, 10) || 0;
            var m = parseInt(mEl.value, 10) || 0;
            var total = r + t + m;
            var allocEl = document.getElementById('allocatedDisplay');
            if (allocEl) allocEl.textContent = '€' + total.toLocaleString() + 'k';
            var bar = document.getElementById('budgetMeterBar');
            if (bar) {
                var pct = Math.min(100, Math.round((total / this.BUDGET_CAP) * 100));
                bar.style.width = pct + '%';
                if (total > this.BUDGET_CAP) {
                    bar.classList.add('verveine-over');
                    bar.style.width = '100%';
                } else {
                    bar.classList.remove('verveine-over');
                }
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('meaningFitDisplay', 'domainState.meaningFit');
            uiManager.bind('pharmacyDisplay', 'domainState.pharmacyTrust');
            uiManager.bind('differentiationDisplay', 'domainState.differentiation');
            uiManager.bind('valueDisplay', 'domainState.perceivedValue');
            uiManager.bind('budgetDisplay', 'domainState.budgetSpent', function(v) {
                var remaining = (2400 - (v || 0)) / 1000;
                return '€' + remaining.toFixed(2) + 'M';
            });
            uiManager.bind('deadlineDisplay', 'currentPeriod', function(v) {
                var weeks = [16, 12, 8, 4];
                return weeks[Math.min(v - 1, 3)];
            });
            uiManager.bind('listingDisplay', 'domainState.listingStatus', function(v) {
                var t = window.mySimulation.t.bind(window.mySimulation);
                if (v === 'secured') return t('listing_secured');
                if (v === 'rejected') return t('listing_rejected');
                return t('listing_pending');
            });
            uiManager.bind('intentDisplay', 'domainState.purchaseIntent', function(v) {
                if (!v) return '—';
                return v + '%';
            });

            var self = this;
            ['redesignInput', 'tradeInput', 'marketingInput'].forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() { self._updateBudgetMeter(); });
                }
            });
            this._updateBudgetMeter();
        }

