        getChartData(state) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            var ds = state.domainState;
            var labels = ds.fitHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                meaningChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.fitHistory },
                        { data: ds.pharmacyHistory },
                        { data: ds.diffHistory },
                        { data: ds.valueHistory }
                    ]
                },
                positionChart: {
                    labels: [t('chart_ds_fit_short'), t('chart_ds_pharm'), t('chart_ds_diff'), t('chart_ds_value')],
                    datasets: [
                        { data: [ds.meaningFit, ds.pharmacyTrust, ds.differentiation, ds.perceivedValue] },
                        { data: [55, 62, 45, 50] }
                    ]
                }
            };
        }

        // Shared composite (0-100). Single source of truth for the per-period score written to
        // domainState.performance.overallScore (reporting/grading layer) AND the debrief. Weights
        // & listing bonus/penalty identical to v1.0.0.
        _composite(r) {
            var fit = r.meaningFit || 0, pharm = r.pharmacyTrust || 0, diff = r.differentiation || 0;
            var value = r.perceivedValue || 0, intent = r.purchaseIntent || 0;
            var totalScore = Math.round(fit * 0.30 + pharm * 0.25 + diff * 0.20 + value * 0.15 + intent * 0.10);
            if (r.listingStatus === 'secured') totalScore = Math.min(100, totalScore + 6);
            if (r.listingStatus === 'rejected') totalScore = Math.max(0, totalScore - 8);
            return Math.max(0, Math.min(100, totalScore));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            var fit = r.meaningFit || 0;
            var pharm = r.pharmacyTrust || 0;
            var diff = r.differentiation || 0;
            var value = r.perceivedValue || 0;
            var intent = r.purchaseIntent || 0;
            var fin = r.financialImpact || 0;

            // Composite: meaning fit (30%), pharmacy trust preserved (25%),
            // differentiation (20%), perceived value (15%), purchase intent (10%).
            var totalScore = this._composite(r);

            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            var performanceKey = 'grade_cosmetic';
            if (totalScore >= 78 && r.outcome === 'won') performanceKey = 'grade_strategist';
            else if (totalScore >= 62) performanceKey = 'grade_capable';
            else if (totalScore >= 45) performanceKey = 'grade_developing';
            var performance = T(performanceKey);

            var insights = [];

            // Diagnosis read-back
            var decodedEver = history.some(function(h) { return h.results && h.results.decodedRight; });
            insights.push(decodedEver ? T('ins_decoded_yes') : T('ins_decoded_no'));

            // Pharmacy betrayal
            insights.push(pharm < 60 ? T('ins_pharm_low') : T('ins_pharm_ok'));

            // Differentiation
            insights.push(diff < 45 ? T('ins_diff_low') : T('ins_diff_ok'));

            // Value encoded vs asserted
            if (value < 50) insights.push(T('ins_value_low'));

            // Listing / financial
            if (r.listingStatus === 'secured') insights.push(T('ins_listing_secured'));
            else if (r.listingStatus === 'rejected') insights.push(T('ins_listing_rejected'));

            return {
                totalScore: totalScore,
                meaningFit: fit,
                pharmacyTrust: pharm,
                differentiation: diff,
                perceivedValue: value,
                purchaseIntent: intent,
                financialImpact: fin,
                listingStatus: r.listingStatus,
                outcome: r.outcome,
                overallScore: totalScore,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore : 0;
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var won = s.outcome === 'won';
            var badge = won
                ? '<span class="db-cm-badge db-cm-yes">' + T('cm_won') + '</span>'
                : '<span class="db-cm-badge db-cm-no">' + T('cm_lost') + '</span>';
            var fin = Math.round((s.financialImpact || 0) * 10) / 10;
            var finStr = (fin < 0 ? '\u2212\u20ac' + Math.abs(fin) + 'M' : '\u20ac' + fin + 'M');
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="db-cm-metric"><span class="db-cm-mv">' + Math.round(s.meaningFit||0) + '</span><span class="db-cm-ml">' + T('cm_m_fit') + '</span></div>'
                + '<div class="db-cm-metric"><span class="db-cm-mv">' + Math.round(s.pharmacyTrust||0) + '</span><span class="db-cm-ml">' + T('cm_m_pharm') + '</span></div>'
                + '<div class="db-cm-metric"><span class="db-cm-mv">' + Math.round(s.differentiation||0) + '</span><span class="db-cm-ml">' + T('cm_m_diff') + '</span></div>'
                + '<div class="db-cm-metric"><span class="db-cm-mv">' + finStr + '</span><span class="db-cm-ml">' + T('cm_m_fin') + '</span></div>';
            return ''
                + '<div class="db-completion">'
                +   '<div class="db-cm-head">'
                +     '<div class="db-cm-score">' + score + '<span class="db-cm-score-max">/100</span></div>'
                +     '<div class="db-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="db-cm-metrics">' + metrics + '</div>'
                +   '<div class="db-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="db-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.outcome === 'won') return window.mySimulation.t('hint_won');
            if (results.outcome === 'lost' && state.currentPeriod >= 4) return window.mySimulation.t('hint_lost');
            if (!results.decodedRight && results.dominantCode === 'none') return window.mySimulation.t('hint_cosmetic');
            if (!results.decodedRight) return window.mySimulation.t('hint_wrong_code');
            if (results.pharmacyTrust < 62) return window.mySimulation.t('hint_pharmacy');
            if (results.differentiation < 45) return window.mySimulation.t('hint_generic');
            if (results.listingStatus === 'rejected') return window.mySimulation.t('hint_listing');
            if (results.defense === 'claim') return window.mySimulation.t('hint_claim');
            return window.mySimulation.t('hint_good_progress');
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.dominantCode', label: 'Decoded Code', i18nKey: 'col_code', formatter: function(v) {
                    var t = window.mySimulation.t.bind(window.mySimulation);
                    var map = { sachet: 'code_short_sachet', serif: 'code_short_serif', green: 'code_short_green', none: 'code_short_none' };
